INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES
('208d3cc5-7124-59a2-82c0-2ccc0bed0213', '253ab84b-cde9-51ca-a335-bf2e720e7d51', 'tr', $h$Diyaframlı Pompa$h$, $h$diyaframli-pompa$h$, $h$Diyaframlı Pompa – Endüstriyel Sıvı Transferinde Esneklik ve Güven$h$, $h$<div> <p><strong>Diyaframlı pompalar</strong>, elastik bir diyafram sayesinde sıvıyı mekanik temas olmadan transfer eden pozitif deplasmanlı pompalar olarak endüstriyel proseslerde yüksek verim ve dayanıklılık sağlar. Toz, kir ve parçacık içeren akışkanlarda dahi performans düşmeden çalışabilmesiyle öne çıkar.</p><p>Bu pompalar, <strong>yüksek viskoziteli, aşındırıcı veya kirli sıvıların</strong> güvenli ve kontrollü taşınmasında ideal çözüm sunar. Marin ve endüstriyel ortamlarda sıvı transfer hattı güvenliğini en üst düzeye çıkarmak için tasarlanmıştır.</p> </div><div> <p><strong>HD Marine diyaframlı pompalar</strong>;</p><ul><li>Yüksek verimli pozitif deplasman sağlayarak <strong>daha stabil akış</strong> sunar</li><li>Aşındırıcı ve kirli sıvılarla çalışırken <strong>uzun ömürlü performans</strong> sağlar</li><li>Deniz ve endüstri ortamlarına uygun <strong>sağlam ve dayanıklı yapı</strong> ile üretim hattınızda güven oluşturur</li></ul> </div>$h$, $h$<div> <p>Diyaframlı pompalar özellikle:</p><ul><li>Kimya ve petrokimya tesislerinde</li><li>Gıda ve farmasötik üretim hatlarında</li><li>Atık su ve filtrasyon tesislerinde</li><li>Boya, baskı ve solvent transfer uygulamalarında</li><li>Marin makinelerinde</li></ul><p>gibi çok çeşitli endüstriyel ve denizcilik uygulamalarında güvenilir performans sağlar.</p> </div>$h$, $h$Diyaframlı Pompa | HD Marine$h$, $h$Diyaframlı pompalar , elastik bir diyafram sayesinde sıvıyı mekanik temas olmadan transfer eden pozitif deplasmanlı pompalar olarak endüstriyel…$h$, 'reviewed'),
('10db8c21-349e-5d8a-a29e-944d1a59b41e', '0de57938-4e61-5dce-9e4f-666656979eda', 'tr', $h$Dişli Pompa$h$, $h$disli-pompa$h$, $h$Dişli Pompa – Endüstriyel Sıvı Transfer Çözümleri$h$, $h$<div> <p><strong>Dişli pompalar</strong>, pozitif deplasmanlı çalışması sayesinde her devride sabit miktarda sıvı transferi sağlayan mekanik pompalar olarak endüstriyel sistemlerde sıklıkla tercih edilir. Bu özellikleriyle özellikle viskoz (yoğun) sıvıların taşınmasında yüksek performans ve güvenilirlik sunar.</p><p>Dişli pompalar, <strong>yüksek basınçlı transfer</strong>, <strong>düşük debi uygulamaları</strong> ve <strong>sürekli akış kontrolü gereken sistemler</strong> için ideal çözümlerdir. Bu pompalar içlerindeki dişli çarklar vasıtasıyla sıvıyı emer, basınçlandırır ve istikrarlı şekilde sistem hattına iletir.</p><p>HD Marine dişli pompalar, geniş viskozite aralığındaki sıvıları problemsiz şekilde transfer edebilme kapasitesi ile endüstriyel tesislerden üretim hatlarına kadar çeşitli uygulamalarda etkinlik sağlar.</p> </div><div> <p>✔ <strong>Sabit debi akışı:</strong> Her devirde aynı hacimde sıvı transferi sağlar. <br/>✔ <strong>Yüksek viskozite uyumu:</strong> Yağlar, reçineler, kimyasallar ve yoğun sıvılar için uygundur. <br/>✔ <strong>Düşük devirde yüksek verim:</strong> Düşük motor hızlarında bile istenen basınç ve debiyi sağlar. <br/>✔ <strong>Güvenilir performans:</strong> Endüstriyel süreçlerde sürekli ve stabil çalışma sunar.</p> </div>$h$, $h$<div> <p>Dişli pompalar; başta üretim tesisleri, kimya ve petrokimya hatları, yağlama sistemleri, pano ve hidrolik devreler ile viskoz sıvı transferi gerektiren tüm endüstriyel uygulamalarda efektif olarak kullanılır.</p> </div>$h$, $h$Dişli Pompa | HD Marine$h$, $h$Dişli pompalar , pozitif deplasmanlı çalışması sayesinde her devride sabit miktarda sıvı transferi sağlayan mekanik pompalar olarak endüstriyel…$h$, 'reviewed'),
('9d67cc22-e8b0-5d40-aaff-0628daa2fc63', 'd5901428-7bb2-5759-aeb0-7732a64fb61b', 'tr', $h$Blower$h$, $h$blower$h$, $h$Endüstriyel Blower – Güçlü Hava & Gaz Transfer Çözümleri$h$, $h$<div> <p><strong>Blower</strong>, havayı veya gazı yüksek debi ve belirli bir basınç aralığında emip çıkışa ileten endüstriyel hava <strong>üfleme ve vakum cihazıdır</strong>. Endüstriyel proseslerin oksijenlendirilmesi, havalandırma, kurutma, basınçlı hava sağlama veya gaz tahliyesi gibi uygulamalarda etkin rol oynar. Blower’lar, fanlardan daha yüksek basınç ve daha kontrol edilebilir debi üretir ve bu yüzden HVAC, arıtma tesisleri, pnömatik taşıma, proses ekipmanları gibi pek çok alanda tercih edilir.</p> </div><div> <p><strong>✔️ Neden HD Marine Blower?</strong></p><p>HD Marine blower’lar:</p><ul><li><strong>Enerji verimli performans</strong> sağlar</li><li><strong>Düşük titreşim ve uzun ömür</strong> ile dayanıklıdır</li><li>Farklı <strong>debiler ve basınç seviyeleri</strong> için uygun seçenekler sunar</li><li><strong>Kolay montaj ve bakım</strong> yapısı ile işletme maliyetini düşürür</li></ul><p>Bu karakteristikler, blower’ları endüstriyel hava taşıma ve proses ekipmanı içinde güvenilir bir çözüm haline getirir.</p> </div><div> <p>✔ <strong>Yüksek hava / gaz debisi:</strong> Büyük hacimli hava akışı sağlar <br/>✔ <strong>Basınç arttırma kapasitesi:</strong> Fanlara göre daha yüksek basınç üretir <br/>✔ <strong>Hava transferi ve vakum uygulamaları:</strong> Hem basma hem çekme yönünde kullanılabilir <br/>✔ <strong>Motor kontrollü hava emişi:</strong> Elektrikli motor sayesinde stabil performans<br/>✔ <strong>Çeşitli tipler:</strong> Santrifüj, rotorlu veya pozitif deplasmanlı modellerle uyumlu <br/>✔ <strong>Dayanıklı gövde:</strong> Endüstriyel çalışma koşullarına uygun</p> </div>$h$, NULL, $h$Blower | HD Marine$h$, $h$Blower , havayı veya gazı yüksek debi ve belirli bir basınç aralığında emip çıkışa ileten endüstriyel hava üfleme ve vakum cihazıdır . Endüstriyel…$h$, 'reviewed'),
('7c9e0b77-551e-5fca-986c-cf8a76dff356', '94151aad-5d35-5bc5-b797-07b8775f2c27', 'tr', $h$Manyetik Asit Pompaları$h$, $h$manyetik-asit-pompalari$h$, $h$Manyetik Asit Pompası – Aşındırıcı Sıvılar İçin Güvenilir Transfer$h$, $h$<div> <p>Manyetik asit pompaları, <strong>asitle, kimyasallarla ve korozif sıvılarla çalışmak için özel üretilmiş manyetik kavramalı pozitif deplasmanlı pompalardır</strong>. Mekanik salmastra yerine manyetik kavrama sayesinde sızdırmazlığı maksimum seviyeye çıkarır ve <strong>kirleticilere, aşındırıcı akışkanlara karşı üstün dayanım sağlar</strong>.</p><p>HD Marine manyetik asit pompaları, özellikle <strong>laboratuvarlardan üretim hatlarına</strong>, kimya tesislerinden marin uygulamalara kadar geniş bir kullanım alanında <strong>yüksek performans ve dayanıklılık</strong> sunar.</p> </div><div> <ul><li><p>✔ <strong>Yüksek kimyasal dayanım:</strong> Sert sıvılarla uzun süreli çalışır<br/>✔ <strong>Sızdırmaz performans:</strong> Manyetik kavrama ile güvenli transfer<br/>✔ <strong>Kolay kurulum:</strong> Kullanıcı dostu montaj yapısı<br/>✔ <strong>Uzun ömürlü yapı:</strong> Minimum bakım ile yüksek dayanıklılık</p></li></ul> </div>$h$, $h$<div> <p>HD Marine manyetik asit pompaları özellikle:</p><ul><li>Kimya üretim tesisleri</li><li>Boya ve solvent hatları</li><li>Su ve atık su arıtma</li><li>Asit/baz transfer sistemleri</li><li>Marin ve endüstriyel prosesler</li></ul><p>gibi <strong>korozif ve aşındırıcı akışkanların güvenli taşınmasını gerektiren</strong> tüm uygulamalarda etkin çözümdür.</p> </div>$h$, $h$Manyetik Asit Pompaları | HD Marine$h$, $h$Manyetik asit pompaları, asitle, kimyasallarla ve korozif sıvılarla çalışmak için özel üretilmiş manyetik kavramalı pozitif deplasmanlı pompalardır .…$h$, 'reviewed'),
('c3043954-e4af-57db-b60f-513aa87fbf62', '8f6fe15a-82df-5840-bd1f-0374353b4006', 'tr', $h$Varil Pompası$h$, $h$varil-pompasi$h$, $h$Varil Pompası – Endüstriyel Sıvı Transferi İçin Pratik Çözüm$h$, $h$<div> <p><strong>Varil pompaları</strong>, varil, bidon ve silindir tipi depolama tanklarındaki sıvıların hızlı, kontrollü ve ergonomik bir şekilde transfer edilmesine olanak sağlayan endüstriyel ekipmanlardır. Yağ, kimyasal, solvent, yakıt ve diğer akışkanların taşınmasında ideal performans sunar.</p><p>HD Marine varil pompaları; dayanıklı yapısı, kolay montajı ve geniş uygulama uyumu ile hem endüstriyel tesislerde hem de marin süreçlerde güvenilir bir sıvı transfer çözümüdür.</p> </div><div> <p>✔ <strong>Pratik montaj:</strong> Çeşitli varil çaplarına uygundur<br/>✔ <strong>Dayanıklı yapı:</strong> Kimyasal ve solvent dayanımı yüksek materyaller<br/>✔ <strong>Çeşitli sürüş seçenekleri:</strong> Elle, elektrikli veya havalı çalışma<br/>✔ <strong>Kolay kullanım:</strong> Ergonomik pompa yapısı ile hızlı transfer<br/>✔ <strong>Geniş uygulama uyumu:</strong> Yağ, yakıt, kimyasal, asit, baz transferi</p> </div>$h$, NULL, $h$Varil Pompası | HD Marine$h$, $h$Varil pompaları , varil, bidon ve silindir tipi depolama tanklarındaki sıvıların hızlı, kontrollü ve ergonomik bir şekilde transfer edilmesine olanak…$h$, 'reviewed'),
('cb2f852c-35da-53c6-bc00-8d97f2581bb5', 'dafeaf56-2575-5e8d-82f5-c1a62bf5b04a', 'tr', $h$Vakum Pompası$h$, $h$vakum-pompasi$h$, $h$Vakum Pompası – Etkili Hava/Boşluk Kontrolü İçin Güçlü Çözüm$h$, $h$<div> <p><strong>Vakum pompaları</strong>, içindeki hava veya gaz moleküllerini çekerek bir sistemde negatif basınç oluşturur. Bu sayede <strong>vakumlu ortam yaratma, gaz tahliyesi ve ortam havasını boşaltma</strong> gibi kritik endüstriyel uygulamalarda güvenilir performans sağlar. Sanayi, kimya, laboratuvar, üretim hatları, paketleme ve proses kontrol sistemlerinde yaygın şekilde kullanılır.</p><p>HD Marine vakum pompaları, dayanıklı yapısı, hassas emiş gücü ve yüksek verimliliği ile <strong>sürekli çalışma koşullarında dahi etkin sonuç sunar.</strong></p> </div><div> <p>✔ <strong>Yüksek çekiş kapasitesi:</strong> Stabil ve hızlı vakumlama<br/>✔ <strong>Enerji tasarrufu:</strong> Uzun süreli kullanımlarda düşük enerji tüketimi<br/>✔ <strong>Geniş uyumluluk:</strong> Farklı endüstri tipleri ile entegre<br/>✔ <strong>Kullanıcı dostu tasarım:</strong> Kolay kurulum ve bakım</p> </div>$h$, $h$<div> <p>HD Marine vakum pompaları özellikle:</p><ul><li>Endüstriyel proses hatları</li><li>Laboratuvar uygulamaları</li><li>Paketleme makineleri</li><li>Kimya tesisleri</li><li>HVAC ve kurutma sistemleri</li><li>Elektronik üretim hatları</li></ul><p>gibi <strong>gaz tahliyesi, vakumlu ortam gerektiren prosesler</strong> için uygundur.</p> </div>$h$, $h$Vakum Pompası | HD Marine$h$, $h$Vakum pompaları , içindeki hava veya gaz moleküllerini çekerek bir sistemde negatif basınç oluşturur. Bu sayede vakumlu ortam yaratma, gaz tahliyesi ve…$h$, 'reviewed'),
('4dbeeaf8-6428-5ad1-87e7-62c06c82acc8', 'aa6ce44f-15fa-545f-b6b8-6a15f304eb00', 'tr', $h$Dozaj Pompası$h$, $h$dozaj-pompasi$h$, $h$Dozaj Pompası – Hassas ve Güvenilir Sıvı Dozlama Çözümü$h$, $h$<div> <p><strong>Dozaj pompaları</strong>, belirli bir akışkanı <strong>belirlenmiş oran ve debide</strong> sisteme eklemek için tasarlanmış yüksek hassasiyetli endüstriyel pompalardır. Su arıtma, kimya, gıda üretimi, atık su işlemleri ve proses kontrol uygulamalarında sıklıkla kullanılır. Doğru dozlama imkânı sayesinde <strong>üretilen ürün kalitesini yükseltir, maliyetleri düşürür ve proses verimliliğini artırır.</strong></p><p>HD Marine dozaj pompaları, <strong>ayarlanabilir debi kontrolü ve dayanıklı yapısı</strong> ile her ölçekte endüstriyel sistemde stabil ve tekrarlanabilir performans sağlar.</p> </div><div> <p>✔ <strong>Yüksek hassasiyet:</strong> Ölçülen sıvı miktarı üst seviyede tutarlılık<br/>✔ <strong>Enerji verimliliği:</strong> Uzun süreli kullanımlarda düşük enerji tüketimi<br/>✔ <strong>Kolay bakım:</strong> Modüler yapısı sayesinde hızlı servis<br/>✔ <strong>Geniş uygulama uyumu:</strong> Birçok endüstriyel proses için esnek kullanım</p> </div>$h$, $h$<div> <p>HD Marine dozaj pompaları aşağıdaki sektörlerde güvenilir şekilde kullanılır:</p><ul><li><strong>Su ve atık su arıtma tesisleri</strong></li><li><strong>Kimya ve petrokimya endüstrisi</strong></li><li><strong>Gıda ve içecek üretimi</strong></li><li><strong>Boyama ve tekstil prosesleri</strong></li><li><strong>Isıtma, soğutma ve HVAC sistemleri</strong></li><li><strong>Sanayi proses otomasyonu</strong></li></ul><p>Bu pompalar, kontrollü ve sürekli dozaj gerektiren bütün uygulamalarda yüksek doğruluk sağlar.</p> </div>$h$, $h$Dozaj Pompası | HD Marine$h$, $h$Dozaj pompaları , belirli bir akışkanı belirlenmiş oran ve debide sisteme eklemek için tasarlanmış yüksek hassasiyetli endüstriyel pompalardır. Su arıtma,…$h$, 'reviewed'),
