INSERT INTO product_faq_translations (id, faq_id, locale, question, answer) VALUES
('7941a799-6029-50ad-be90-6bbaf9d522c6', 'a1f2922c-2b29-5af3-a1f2-37ea546d8294', 'tr', $h$Diyaframlı pompa nasıl çalışır?$h$, $h$<div> <p>Bir esnek diyaframın ileri–geri hareketi ile sıvı emilerek basılır; akışkan ile mekanik sürtünme olmaz.</p> </div>$h$),
('f66869b9-89d2-56e2-985a-f460dfde8b48', '0ef27e6e-dc8f-5ed2-a7a7-84bc36089eda', 'tr', $h$Hangi sıvılarda tercih edilir?$h$, $h$<div> <p>Partikül içeren, aşındırıcı, kimyasal veya çözünebilen sıvılarda etkilidir.</p> </div>$h$),
('88abe287-d5bf-52c1-a439-794ef29ddab0', '95309ff1-b960-57d1-bafc-29901a482bc1', 'tr', $h$Diyaframlı pompa ile santrifüj pompa farkı nedir?$h$, $h$<div> <p>Diyaframlı pompalar pozitif deplasman ile sabit hacimde sıvı taşırken, santrifüj pompalar akışkanı santrifüj kuvvetle iletir.</p> </div>$h$),
('4629ddb4-78a5-5547-ac2b-0efa0a33872d', 'd0d30ee7-e267-5637-9d2a-343089fd5d18', 'tr', $h$Türkiye’de hangi sektörlerde kullanılır?$h$, $h$<div> <ul><li>Kimya, boya–solvent, gıda–ilaç, atıksu, marin ve endüstriyel tesislerde yaygındır.</li></ul> </div>$h$),
('58b05581-7079-53eb-868c-46decfb50f96', '00597b28-bc2a-551b-a837-10d36a33ec60', 'tr', $h$Dişli pompa ne işe yarar?$h$, $h$<div> <p>Dişli pompalar, dişliler vasıtasıyla sıvıyı sabit bir hacimde emip basarak düzgün bir transfer sağlar.</p> </div>$h$),
('8a574735-7f96-5c9c-b89f-852fea9e1205', 'b345ab44-23dd-57b8-a64a-664822710a70', 'tr', $h$Hangi sıvılarda kullanılır?$h$, $h$<div> <p>Yağlar, reçineler, kimyasal sıvılar ve yüksek viskoziteli akışkanlarda etkilidir.</p> </div>$h$),
('8814e261-b5e9-51b1-833d-dda4bb10e08b', 'b13820c3-1c22-547c-857a-4d31f01fcd1b', 'tr', $h$Dişli pompa ile santrifüj pompa arasındaki fark nedir?$h$, $h$<div> <p>Dişli pompalar sabit deplasmanlı akış sağlar; santrifüj pompalar basınç farkıyla debi sağlar.</p> </div>$h$),
('af48e0af-26cd-52e6-955b-1a19d61b4c41', '0a5cc4ab-a5f1-59b5-b224-1a6c6c194ac4', 'tr', $h$Blower nedir?$h$, $h$<div> <p>Blower, havayı veya gazı yüksek debi ve belirli basınç değerlerinde emen ve çıkışa ileten endüstriyel hava/gaz transfer cihazıdır.</p> </div>$h$),
('a6dead61-62c7-50ec-b744-570787186afa', '0b7a55a8-5048-5a01-89c5-054a9ce08b4e', 'tr', $h$Blower ile fan arasındaki fark nedir?$h$, $h$<div> <p>Fanlar genellikle düşük basınçlı hava sirkülasyonu sağlarken blower’lar daha yüksek basınç ve kontrol edilebilir debi ile performans odaklıdır.</p> </div>$h$),
('73107dc5-5832-5442-8bc0-e3daef02012a', '8d96907e-06a0-5227-84e6-401aa535cc4e', 'tr', $h$Hangi uygulamalarda kullanılır?$h$, $h$<div> <p>Havalandırma, pnömatik taşıma, kurutma, atıksu arıtma ve marin hava tahliye süreçlerinde kullanılır.</p> </div>$h$),
('9ba984a6-4c20-5ded-b3cd-5c0dda6954cc', '8ca628ba-7681-5d8f-8030-dfff77071760', 'tr', $h$Blower seçiminde nelere dikkat edilmelidir?$h$, $h$<div> <p>Gerekli hava debisi, istenen basınç seviyesi, ortam sıcaklığı ve motor gücü blower seçiminde önemli kriterlerdir.</p> </div>$h$),
('149aed37-567c-51fd-b859-60ad2464bd69', 'e2b38441-f993-5429-820e-3dd9699be755', 'tr', $h$Manyetik asit pompası nedir?$h$, $h$<div> <p>Manyetik kavramalı pozitif deplasmanlı pompa olup, mekanik salmastra yerine manyetik sürüş kullanarak sızdırmaz transfer sağlar.</p> </div>$h$),
('fb17ca60-af21-5d95-8e25-db577bff24a3', '04a0dd5d-dd6b-5f8e-9618-2500aea3e365', 'tr', $h$Kimyasal sıvılar için mi uygundur?$h$, $h$<div> <p>Evet, asit, baz ve kimyasal reaksiyon sıvılarının transferi için geliştirilmiştir.</p> </div>$h$),
('e8b6a535-6ec3-5801-8577-a797c8378fff', '8523b925-b1c8-5ad0-bbd4-031057225675', 'tr', $h$Salmastra neden kullanılmaz?$h$, $h$<div> <p>Manyetik kavrama sayesinde salmastra ihtiyacı azalır; sızdırmazlık ve bakım avantajı sağlar.</p> </div>$h$),
('fe225b42-fb2c-50d7-9b8a-0656812f50d6', '6c718d69-d859-506b-84d5-59fbac45353e', 'tr', $h$Nerelerde kullanılmalıdır?$h$, $h$<div> <p>Kimya fabrikaları, su arıtma, boya hattı ve endüstriyel proseslerde tercih edilir.</p> </div>$h$),
('9681647c-cb62-5e08-828f-522bd7da8205', '5dbaab34-afd1-531c-8166-d0e7ca651ab9', 'tr', $h$Varil pompası nedir?$h$, $h$<div> <p>Varil pompası, varil, bidon ve tank içerisindeki sıvıları ergonomik ve kontrollü şekilde dışarı aktarabilen özel transfer pompasıdır.</p> </div>$h$),
('eb639453-97d1-5805-a19d-1f1163f35faa', '051d3b1c-196f-553f-9b22-98bfb7353b9b', 'tr', $h$Hangi sıvılarla kullanılabilir?$h$, $h$<div> <p>Yağlar, kimyasallar, solventler, yakıtlar ve çeşitli akışkan tipleri için uygun modeller bulunur.</p> </div>$h$),
('db33613e-dfa6-59dd-a69e-9298103685cd', '0c9e1a01-b473-50cb-a9a3-5b496c1dacba', 'tr', $h$Elektrikli varil pompası avantajı nedir?$h$, $h$<div> <p>Elektrikli modeller daha hızlı ve az eforla transfer sağlar; büyük hacimli depolar için uygundur.</p> </div>$h$),
('9de04d3c-a465-5c1a-b51a-a864c28f0d24', '467085c4-2d6b-5767-8bd9-364c6770fbce', 'tr', $h$Pompa malzemesi nasıl seçilir?$h$, $h$<div> <p>Taşınacak sıvının kimyasal yapısına göre gövde ve conta malzemesi (PP, alüminyum, paslanmaz çelik, Viton vb.) seçilmelidir.</p> </div>$h$),
('39d61b97-86fc-52b3-8809-91d4e94f15fa', 'd2a4f83b-27ee-5193-aa3e-20a6a11b7e91', 'tr', $h$Vakum pompası nedir?$h$, $h$<div> <p>Vakum pompası, bir sistemdeki hava veya gazları çekerek negatif basınç oluşturur ve vakumlu ortam sağlar.</p> </div>$h$),
('c957cd4a-e615-5a28-a661-4b2bcc2aea4c', '16db7546-bb0f-5158-b7ef-b45226a0a79f', 'tr', $h$Hangi sektörlerde kullanılır?$h$, $h$<div> <p>Endüstri, laboratuvar, üretim hatları, paketleme ve kimya tesislerinde yaygın olarak kullanılır.</p> </div>$h$),
('b11bdd6e-c52c-5644-9d51-165611dd7a5b', 'b0dbb3e9-490b-55cd-a658-627f4ac38f89', 'tr', $h$Vakum ve basınç pompası arasındaki fark nedir?$h$, $h$<div> <p>Vakum pompası negatif basınç oluşturarak havayı çeker; basınç pompası ise akışkanı iter.</p> </div>$h$),
('a1966972-d157-5bc1-8a08-ea5e47bf23a5', 'e33f2e87-834a-5d05-90f0-c6c8f495f4b8', 'tr', $h$Vakum pompada bakım ne sıklıkla yapılmalı?$h$, $h$<div> <p>Çalışma koşullarına bağlı olarak periyodik yağ değişimi ve sızıntı kontrolleri önerilir.</p> </div>$h$),
('e73d409d-7fb0-5273-adcb-4ede8008230c', 'bf9e337c-8d98-5214-8e62-0681c7b96ac4', 'tr', $h$Diyaframlı pompa nasıl çalışır?$h$, $h$<div> <p>Dozaj pompası, belirli bir hacimde sıvıyı kontrollü ve ayarlanabilir şekilde sisteme eklemek için kullanılır.</p> </div>$h$),
('c243373c-7942-5557-9fa6-3f011a40b848', 'ac7f5894-09b2-5e43-acf3-646c592cee98', 'tr', $h$Hangi sektörlerde tercih edilir?$h$, $h$<div> <p>Su arıtma, kimya üretimi, gıda-içecek hattı, atık su ve proses kontrol uygulamalarında yaygın olarak kullanılır.</p> </div>$h$),
('01686dd2-20f1-5c52-bee0-cf6556976328', '62807921-7499-5ff7-8443-035b48b19ef3', 'tr', $h$Dozaj pompası ile diyaframlı pompa arasındaki fark nedir?$h$, $h$<div> <p>Dozaj pompası hassas ve ayarlanabilir sıvı ekleme için optimize edilir; diyaframlı pompa ise genel pozitif deplasmanlı transfer sağlar.</p> </div>$h$),
('dc9c5452-4b02-582a-b1af-41f088599a52', '0cb3652d-d4ed-5f21-9087-f6608c5b19ff', 'tr', $h$Debi nasıl ayarlanır?$h$, $h$<div> <p>Kontrol paneli ve ayar düğmeleri ile istenen debi kolayca seçilebilir.</p> </div>$h$),
